// AssertStoreContract runs every generated check against every declared subject.
//
//	Subjects: declare each with StoreSubject
//	Extend:   StoreOnPut, StoreOnGet, StoreOnTouch
//	Drop:     StoreWithout, by the path each check reports under
func AssertStoreContract(t *testing.T, opts ...StoreOption) {
	t.Helper()
	cfg := newStoreConfig(opts...)
	if len(cfg.subjects) == 0 {
		t.Fatalf("AssertStoreContract was given no subject; declare one with " +
			"StoreSubject(name, factory)")
	}
	for _, p := range cfg.phantoms() {
		t.Errorf("StoreWithout(%q) declines nothing: no check here reports "+
			"under that path, so this suite asserts one thing more than its "+
			"author believes", p)
	}
	for _, s := range cfg.subjects {
		runStoreChecks(t, cfg, s.name, s.factory, nil)
	}
}

// runStoreChecks runs the whole contract against one subject.
//
// wrap is applied after the subject is built and seeded, so a wrapper is
// transparent to the seed and every failure it causes is its own.
func runStoreChecks(
	t *testing.T,
	cfg *storeConfig,
	label string,
	factory func() receivercollision.Store,
	wrap func(tb testing.TB, subject receivercollision.Store) receivercollision.Store,
) {
	t.Helper()
	t.Run(label, func(t *testing.T) {
		t.Parallel()

		t.Run(storePut, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onPut {
				cfg.run(t, string(suite.MethodID(storePut, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Session)
				})
			}
		})

		t.Run(storeGet, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onGet {
				cfg.run(t, string(suite.MethodID(storeGet, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.S)
				})
			}
		})

		t.Run(storeTouch, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onTouch {
				cfg.run(t, string(suite.MethodID(storeTouch, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.Session)
				})
			}
		})

		// The extra bodies of checks this run was given, each reporting under its
		// own name and dropped by it.
		//
		// The plain subject only. The wrapped pass exists to prove the double
		// faithful and the per-method checks above already do that, so running one
		// through the wrapper prices the wrapper and says nothing new about the
		// subject.
		if wrap == nil {
			for _, e := range cfg.extensions {
				if cfg.declined(e.name) {
					t.Run(e.name, func(t *testing.T) {
						t.Skipf("dropped through StoreWithout(%q)", e.name)
					})
					continue
				}
				t.Run(e.name, func(t *testing.T) {
					t.Parallel()
					e.run(t, label, factory, cfg)
				})
			}
		}
	})
}

// StoreOption configures a contract run.
type StoreOption func(*storeConfig)

// StoreSubject declares an implementation to hold to the contract.
//
// Repeat it for every implementation that claims to satisfy the interface — an
// in-memory one, the one backed by a database, the one behind a network. Every
// check and every option is stated once and runs against all of them, which is
// what a conformance suite is for.
func StoreSubject(name string, factory func() receivercollision.Store) StoreOption {
	return func(c *storeConfig) {
		c.subjects = append(c.subjects, namedStoreSubject{name, factory})
	}
}

// StoreWithClock supplies the clock every time-reading check measures on.
//
// Defaults to the real one, so an implementation that does not take a clock
// behaves as it would have. Supply a [clock.TestClock] — the same one the
// factory builds the subject with — and a budget becomes a claim about the time
// the implementation means to spend rather than about how loaded the machine
// was.
func StoreWithClock(c clock.Clock) StoreOption {
	return func(cfg *storeConfig) { cfg.clock = c }
}

// StoreWithFixture replaces the derived inputs.
func StoreWithFixture(f StoreFixture) StoreOption {
	return func(c *storeConfig) { c.Fixture = f }
}

// StoreSeed replaces the derived seed.
//
// For an interface with no writer to seed itself through, which is the one
// input a conformance run cannot derive: a reader over an empty subject
// asserts nothing.
//
// Returning an error rather than swallowing one. A seed that failed quietly
// leaves every check after it asserting nothing and reporting success.
func StoreSeed(fn func(ctx context.Context, subject receivercollision.Store) error) StoreOption {
	return func(c *storeConfig) {
		c.seed = fn
		c.seedIsDerived = false
	}
}

// StoreOnPut adds a named check to Put.
func StoreOnPut(name string, fn StorePutCheck) StoreOption {
	return func(c *storeConfig) {
		c.onPut = append(c.onPut, namedStorePutCheck{name, fn})
	}
}

// StoreOnGet adds a named check to Get.
